  padding: 72px 0;
  background: linear-gradient(180deg, #fbf8f2 0%, #ffffff 100%);
}

.container {
  width: min(960px, 100% - 2rem);
  margin: 0 auto;
}

.account-card {
  background: #ffffff;
  border-radius: 28px;
  padding: clamp(1.5rem, 4vw, 3rem);
  box-shadow: 0 22px 60px rgba(8, 38, 58, 0.12);
  border: 1px solid rgba(8, 38, 58, 0.08);
}

.eyebrow {
  display: inline-block;
  color: #0b6e8f;
  font-family: "Raleway", Arial, sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.75rem;
  font-weight: 700;
  margin-bottom: 0.8rem;
}

h1 {
  font-family: "Playfair Display", Georgia, serif;
  color: #08263a;
  margin: 0 0 1rem;
  font-size: clamp(2rem, 5vw, 3.2rem);
}

p {
  font-family: "Lato", Arial, sans-serif;
  color: #2f3a45;
  line-height: 1.7;
}

.account-empty {
  margin-top: 2rem;
  padding: 1.25rem;
  border-radius: 20px;
  background: #e8f4f7;
}

.btn {
  display: inline-flex;
  margin-top: 0.8rem;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  border-radius: 999px;
  padding: 0.9rem 1.2rem;
  font-family: "Raleway", Arial, sans-serif;
  font-weight: 700;
}

.btn-primary {
  background: #f28c28;
  color: #fff;
}

.payment-toolbar {
  display: grid;
  grid-template-columns: repeat(3, minmax(160px, 1fr)) auto;
  gap: 0.85rem;
  align-items: end;
  margin: 2rem 0 1rem;
}

.payment-toolbar label {
  display: grid;
  gap: 0.35rem;
  color: #08263a;
  font-family: "Raleway", Arial, sans-serif;
  font-weight: 700;
}

.payment-toolbar select {
  min-height: 42px;
  border: 1px solid rgba(8, 38, 58, 0.16);
  border-radius: 14px;
  padding: 0.65rem 0.75rem;
  background: #fff;
  font: inherit;
}

.payment-summary {
  margin: 1rem 0;
  color: #516070;
}

.payments-list {
  display: grid;
  gap: 0.85rem;
  margin-top: 1rem;
}

.payment-row {
  display: grid;
  grid-template-columns: 180px 1fr 140px 130px;
  gap: 1rem;
  align-items: center;
  width: 100%;
  text-align: left;
  border: 1px solid rgba(8, 38, 58, 0.08);
  border-radius: 20px;
  background: #fff;
  padding: 1rem;
  cursor: pointer;
  box-shadow: 0 12px 28px rgba(8, 38, 58, 0.06);
}

.payment-row:hover {
  transform: translateY(-1px);
  box-shadow: 0 16px 34px rgba(8, 38, 58, 0.1);
}

.payment-type {
  display: inline-flex;
  justify-content: center;
  border-radius: 999px;
  padding: 0.55rem 0.8rem;
  background: rgba(8, 38, 58, 0.08);
  color: #08263a;
  font-weight: 800;
  font-size: 0.82rem;
}

.payment-type.type-deposit {
  background: rgba(4, 120, 87, 0.12);
  color: #047857;
}

.payment-type.type-balance {
  background: rgba(11, 110, 143, 0.12);
  color: #0b6e8f;
}

.payment-type.type-warranty_card,
.payment-type.type-warranty_cash {
  background: rgba(181, 139, 74, 0.16);
  color: #8a652d;
}

.payment-type.type-warranty_charge,
.payment-type.type-cash_damage {
  background: rgba(185, 28, 28, 0.1);
  color: #b91c1c;
}

.payment-main {
  display: grid;
  gap: 0.2rem;
}

.payment-main strong {
  color: #08263a;
}

.payment-main small,
.payment-amount small {
  color: #516070;
}

.payment-amount {
  display: grid;
  gap: 0.2rem;
  text-align: right;
}

.payment-amount strong {
  color: #08263a;
  font-size: 1.1rem;
}

.payment-open {
  color: #b58b4a;
  font-weight: 800;
  text-align: right;
}

.btn-secondary {
  background: #efe7da;
  color: #08263a;
}

.muted {
  color: #667;
}

@media (max-width: 900px) {
  .payment-toolbar {
    grid-template-columns: 1fr 1fr;
  }
  .payment-row {
    grid-template-columns: 1fr;
  }
  .payment-amount,
  .payment-open {
    text-align: left;
  }
}
@media (max-width: 560px) {
  .payment-toolbar {
    grid-template-columns: 1fr;
  }
