  padding: 80px 0;
  background: #f6f2ea;
  min-height: 70vh;
}

.terms-shell {
  max-width: 980px;
  margin: 0 auto;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.78rem;
  color: #b58b4a;
  font-weight: 700;
}

h1 {
  color: #08263a;
  margin: 8px 0 16px;
}

.intro {
  color: #516070;
  max-width: 820px;
  line-height: 1.7;
}

.terms-card {
  background: #fff;
  border-radius: 24px;
  padding: 32px;
  margin-top: 28px;
  box-shadow: 0 18px 45px rgba(8, 38, 58, 0.08);
  border: 1px solid rgba(8, 38, 58, 0.08);
}

.terms-card h2 {
  color: #08263a;
  margin-top: 2rem;
}

.terms-card h2:first-child {
  margin-top: 0;
}

.terms-card p,
.terms-card li {
  color: #516070;
  line-height: 1.7;
}

.process-step {
  background: #f8f5ef;
  border-radius: 18px;
  padding: 1.25rem;
  margin: 1rem 0;
  border: 1px solid rgba(8, 38, 58, 0.06);
}

.process-step h3 {
  margin-top: 0;
  color: #08263a;
}

@media (max-width: 720px) {
  .terms-page {
    padding: 48px 0;
  }
  .terms-card {
    padding: 22px;
  }
